    if not markers or not top or not bottom:
        return g
    top_row = max(r for r, c in top)
    bottom_row = min(r for r, c in bottom)
    top_cols = [c for r, c in top if r == top_row]
    lo = min([c for r, c in top + bottom])
    hi = max([c for r, c in top + bottom])
    fill = markers[0][2]
    deepest = max(r for r, c, v in markers)
    for c in top_cols:
        for r in range(top_row+1, deepest+1):
            if g[r][c] == bg:
                g[r][c] = fill
    for r, c, color in markers:
        for rr in range(r+1, bottom_row):
            if g[rr][c] == bg:
                g[rr][c] = color
        g[r][c] = 4
